function validate([x, y]) {
  if (!Number.isInteger(x) || !Number.isInteger(y)) return 'x and y must be integers.';
  if (Math.abs(x) > 300 || Math.abs(y) > 300) return 'x and y are between -300 and 300.';
  if (Math.abs(x) + Math.abs(y) > 300) return '|x| + |y| must be at most 300.';
  return null;
}

