function minKnightMoves(x, y) {
  // Plain breadth-first search over the whole plane, with no symmetry and no bounds.
  const dist = new Map([['0,0', 0]]);
  const queue = [[0, 0]];
  for (let head = 0; head < queue.length; head++) {
    const [a, b] = queue[head];
    const d = dist.get(a + ',' + b);
    if (a === x && b === y) return d;
    for (const [da, db] of [[1, 2], [2, 1], [2, -1], [1, -2], [-1, -2], [-2, -1], [-2, 1], [-1, 2]]) {
      const key = (a + da) + ',' + (b + db);
      if (!dist.has(key)) { dist.set(key, d + 1); queue.push([a + da, b + db]); }
    }
  }
  return -1;
}

