function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') return [int(-5, 5), int(-5, 5)];
  // Far targets with |x| + |y| close to the limit of 300.
  const x = int(-300, 300);
  const room = 300 - Math.abs(x);
  const y = (rand() < 0.5 ? -1 : 1) * int(Math.max(0, room - 20), room);
  return [x, y];
}
